doc=App.getDocument("hook_lesson3")
for o in doc.Objects:
    print(o.Name,o.Label,o.TypeId)
    if hasattr(o,'Shape') and o.Shape.Solids:
        s=o.Shape;print(' bbox',s.BoundBox,'vol',s.Volume)
    for p in ('Support','Profile','Length','Type','Base','Placement','Reversed','Midplane','Radius','Size','Spreadsheet'):
        if hasattr(o,p):print(' ',p,getattr(o,p))
    if o.TypeId=='Spreadsheet::Sheet':
        for c in o.getUsedCells():print('  ',c,o.get(c),o.getAlias(c))
    if o.TypeId=='Sketcher::SketchObject':
        print(' geo',[str(g) for g in o.Geometry]);print(' exp',o.ExpressionEngine)
